const D = { density:.55, energy:.6, hue:205, speed:1, scale:1, warp:.3, x:.5, y:.4, seed:0, style:'reflective', act:'calm' };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const fr = i => { const q = Math.sin(i*127.1 + P.seed*311.7) * 43758.5453; return q - Math.floor(q); };
const cl = (v,a,b) => v<a?a:v>b?b:v;
const TAU = 6.28318530718;
const sty = P.style, H = P.hue;
const hz = cl(P.y, .22, .68) * height;
const cx = cl(P.x, .1, .9) * width;
const groundH = Math.max(24, height - hz);
const yOf = t => hz + Math.pow(cl(t,0,1), 1.6) * groundH;   // t 0=far 1=near
const u = Math.min(width, height);

S.bass = (S.bass||0)*.78 + (A.bass||0)*.22;
S.tre  = (S.tre||0)*.8 + (A.treble||0)*.2;
const glow = (.4 + .6*P.energy) * (.5 + .55*K.intensity);
const kick = Math.min(1, K.pulse*(.5 + .5*K.intensity) + S.bass*.7);

// real-time current drift (never re-phases)
if (S.pt == null || K.t < S.pt) S.pt = K.t;
let dt = K.t - S.pt; S.pt = K.t; dt = cl(dt, 0, .1);
let sp = P.speed * (.55 + .8*K.intensity);
if (P.act === 'storm') sp *= .6 + 1.3*kick;
if (P.act === 'tide')  sp *= .35 + 1.0*(.5 + .5*Math.sin(K.t*.05 + K.section*.9));
S.drift = (S.drift||0) + dt*sp;
const drift = S.drift;

// cached water/sky base: reflected gradient below horizon
const key = width+'x'+height+'|'+sty+'|'+Math.round(H)+'|'+Math.round(P.y*20)+'|'+Math.round(P.scale*8);
if (!S.base || S.key !== key) {
  const g = (S.base && S.base.width===width && S.base.height===height) ? S.base : createGraphics(width, height);
  g.colorMode(HSB,360,100,100,100); g.clear(); g.noStroke();
  const STR = 60;
  for (let i=0;i<STR;i++){ const f=i/STR, y=hz + f*groundH, t=f;   // near horizon dark, deep foreground brighter reflection
    let h,s,b;
    if (sty==='ink'){ h=H; s=6; b=cl(30 - 20*t + 8*Math.sin(t*9), 6, 46); }
    else if (sty==='sonar'){ h=(H+150)%360; s=70; b=cl(6 + 10*t, 3, 22); }
    else if (sty==='thermal'){ h=cl(250 - 230*t, 0, 300); s=90; b=cl(14 + 24*t, 8, 60); }
    else { h=H; s=cl(70 - 24*t, 20, 85); b=cl(18 + 30*Math.pow(t,1.3), 8, 62); }  // reflective
    g.fill(h, cl(s,0,95), b, 100); g.rect(0, y, width, groundH/STR + 1);
  }
  // faint far shore/horizon band
  g.fill(H, 20, sty==='thermal'?70:40, 60); g.rect(0, hz-2, width, 3);
  S.base = g; S.key = key;
}
image(S.base, 0, 0);

// perspective shimmer lines — the guaranteed real-time motion floor
const NL = Math.round(10 + P.density*26);
push();
for (let i=0;i<NL;i++){
  const t = (i+.5)/NL, y = yOf(t), near = t;
  const amp = (1 + 5*near) * (.6 + .8*glow) * P.scale;
  const freq = (.006 + .02*(1-near)) * (1 + P.warp);
  const ph = drift*1.4 + i*.7;
  if (sty==='sonar'){
    // schematic contour: dashed horizontal iso-lines
    stroke((H+150)%360, 70, 100, (14 + 40*near)*(.5+.6*glow)); strokeWeight(.6 + near*1.2); noFill();
    beginShape();
    for (let x=0;x<=width;x+=10){ const yy = y + Math.sin(x*freq + ph)*amp*.6 + Math.sin(x*freq*2.3 - ph*1.3)*amp*.3; vertex(x, yy); }
    endShape();
  } else if (sty==='ink'){
    // brushed sumi stroke: tapered translucent wash line
    noFill(); stroke(H, 8, cl(50 + 30*near,10,88), (10 + 26*near)*(.5+.6*glow)); strokeWeight(.8 + near*2.6);
    beginShape();
    for (let x=0;x<=width;x+=12){ const yy = y + Math.sin(x*freq + ph)*amp + Math.sin(x*freq*1.7 + ph*.6)*amp*.4; vertex(x, yy); }
    endShape();
  } else {
    // reflective / thermal specular highlight ribbons (additive)
    push(); blendMode(ADD); noFill();
    let h = sty==='thermal' ? cl(60 - 40*near, 0, 60) : (H - 8);
    let s = sty==='thermal' ? 95 : cl(35 - 20*near, 6, 60);
    stroke(h, s, 100, (6 + 30*near*(.4 + .9*S.tre))*(.5+.7*glow)); strokeWeight(.8 + near*2.2);
    beginShape();
    for (let x=0;x<=width;x+=10){ const yy = y + Math.sin(x*freq + ph)*amp + Math.sin(x*freq*2.1 - ph*1.4)*amp*.5; vertex(x, yy); }
    endShape();
    pop();
  }
}
pop();

// expanding rings on bass/beat — spawned from a small pool
S.rings = S.rings || [];
if (S.lb == null || K.beat < S.lb) S.lb = K.beat;
if (Math.floor(K.beat) > Math.floor(S.lb) && S.rings.length < 14){
  const n = Math.floor(K.beat), big = kick > .5 || (n & 1)===0;
  const rx = cx + (fr(n*2)*2-1) * width*.4;
  const rt = .25 + fr(n*2+1)*.7;
  S.rings.push({ x:rx, t0:rt, born:K.t, life: big?3.2:2.0, str: big?1:.55 });
}
S.lb = K.beat;
push(); blendMode(ADD); noFill();
for (let i=S.rings.length-1;i>=0;i--){
  const rg = S.rings[i];
  if (rg.born > K.t) rg.born = K.t;   // t reset guard
  const age = K.t - rg.born;
  if (age > rg.life){ S.rings.splice(i,1); continue; }
  const p = age / rg.life;
  const t = cl(rg.t0 + p*.35, 0, 1);
  const y = yOf(t), rad = (u*.02 + p*u*.4*(.6+.6*rg.str)) * P.scale;
  const a = (1-p) * rg.str * (18 + 30*glow);
  let h = sty==='thermal' ? cl(50 - 30*t, 0, 60) : sty==='sonar' ? (H+150)%360 : (H-6);
  stroke(h, sty==='thermal'?95:cl(30 - 16*t,6,60), 100, cl(a,0,40));
  strokeWeight(.8 + (1-p)*2.4);
  ellipse(rg.x, y, rad*2, rad*.7);
}
pop();

// specular sparkle: twinkling additive dots (treble + baseline)
const NP = Math.round(P.density*60);
push(); blendMode(ADD); noStroke();
for (let i=0;i<NP;i++){
  const lane=fr(i*3), t = .1 + .88*fr(i*3+1), y = yOf(t);
  const tw = .5 + .5*Math.sin(drift*3 + i*2.1);
  const x = lane*width + Math.sin(K.t*.4 + i)*8;
  const sz = (1 + 3.5*t) * (.6 + tw + 1.3*S.tre) * P.scale;
  let h = sty==='thermal' ? 55 : sty==='sonar' ? (H+150)%360 : H;
  fill(h, sty==='thermal'?60:(sty==='ink'?6:24), 100, cl((6 + 30*t)*tw*(.5+.9*glow), 0, 44));
  ellipse(x, y, sz, sz*.7);
}
pop();

blendMode(BLEND);
drawingContext.shadowBlur = 0;
